package com.reiflix.reiflix_local.data.sqlite

import android.database.sqlite.SQLiteDatabase
import java.io.File
import org.json.JSONArray
import org.json.JSONObject

/**
 * Additive schema owner for the existing LibraryStore schema v29.
 *
 * The contract asset remains generated by the retained source-validation workflow. This
 * manager never rebuilds a table, deletes a row, replaces a database file, or silently
 * changes PRAGMA user_version. Incompatible legacy states fail closed for Recovery Mode.
 */
internal object ReiAnixSqliteSchemaManager {
    fun initialize(
        databaseFile: File,
        allowCreate: Boolean,
        contract: JSONObject,
        inspectSchema: (SQLiteDatabase) -> ReiAnixSqliteSchemaSnapshot,
    ): ReiAnixSqliteSchemaSnapshot {
        val existed = databaseFile.exists()
        check(!existed || (databaseFile.isFile && databaseFile.length() > 0L)) {
            "The canonical SQLite file exists but is empty or is not a regular file. No replacement was created."
        }
        check(existed || allowCreate) {
            "The canonical SQLite database is absent and creation was not authorized."
        }
        val parent = databaseFile.parentFile
        check(parent != null && (parent.isDirectory || parent.mkdirs())) {
            "The canonical SQLite data directory is unavailable."
        }
        val database = try {
            if (existed) {
                SQLiteDatabase.openDatabase(databaseFile.absolutePath, null, SQLiteDatabase.OPEN_READWRITE)
            } else {
                SQLiteDatabase.openOrCreateDatabase(databaseFile.absolutePath, null)
            }
        } catch (error: android.database.sqlite.SQLiteException) {
            throw ReiAnixSqliteOpenException("Unable to open the canonical SQLite database for a safe schema migration.", error)
        }
        try {
            database.setForeignKeyConstraintsEnabled(true)
            database.rawQuery("PRAGMA busy_timeout = ${ReiAnixSqliteDatabase.BUSY_TIMEOUT_MS}", null).use { cursor ->
                while (cursor.moveToNext()) Unit
            }
            database.beginTransactionNonExclusive()
            val snapshot: ReiAnixSqliteSchemaSnapshot
            try {
                migrate(database, contract)
                snapshot = inspectSchema(database)
                check(snapshot.supportsCurrentContract) {
                    "Canonical SQLite schema migration did not produce a compatible v29 database: " +
                        snapshot.incompatibilities.joinToString("; ")
                }
                database.setTransactionSuccessful()
            } finally {
                database.endTransaction()
            }
            return snapshot
        } catch (error: android.database.sqlite.SQLiteException) {
            throw ReiAnixSqliteOpenException("Canonical SQLite schema migration failed; the transaction was rolled back.", error)
        } finally {
            database.close()
        }
    }

    fun migrate(database: SQLiteDatabase, contract: JSONObject) {
        val expectedVersion = contract.getInt("schema_version")
        require(expectedVersion == ReiAnixSqliteDatabase.EXPECTED_SCHEMA_VERSION) {
            "Unsupported canonical schema version $expectedVersion."
        }
        val expectedUserVersion = contract.getInt("sqlite_user_version")
        val actualUserVersion = pragmaInt(database, "PRAGMA user_version")
        check(actualUserVersion == expectedUserVersion) {
            "SQLite user_version is $actualUserVersion; expected $expectedUserVersion. No version was overwritten."
        }

        val tables = contract.getJSONArray("tables").strings()
        val existingTables = database.rawQuery(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'",
            null,
        ).use { cursor -> buildSet { while (cursor.moveToNext()) add(cursor.getString(0)) } }
        // On a non-empty database these long-standing tables are canonical data owners.
        // Their disappearance is data-loss evidence, not an instruction to create an empty replacement.
        if (existingTables.isNotEmpty()) {
            val missingCoreTables = setOf("anime", "episodes", "folders") - existingTables
            check(missingCoreTables.isEmpty()) {
                "Canonical database is missing existing core tables: ${missingCoreTables.sorted().joinToString()}. Recovery is required."
            }
        }
        val columns = contract.getJSONObject("columns")
        for (table in tables) {
            requireSafeIdentifier(table)
            if (!tableExists(database, table)) {
                database.execSQL(createTableSql(table, contract))
            } else {
                addMissingColumns(database, table, columns.getJSONArray(table))
            }
        }

        val existingSchemaVersion = if (tableExists(database, SCHEMA_MIGRATIONS_TABLE)) {
            database.rawQuery("SELECT MAX(version) FROM schema_migrations", null).use { cursor ->
                if (cursor.moveToFirst() && !cursor.isNull(0)) cursor.getInt(0) else 0
            }
        } else {
            0
        }
        check(existingSchemaVersion <= expectedVersion) {
            "Database schema migration version $existingSchemaVersion is newer than supported version $expectedVersion."
        }

        // LibraryStore explicitly replaces this index during v29 reconciliation.
        // The transaction restores the previous index if its replacement fails.
        database.execSQL("DROP INDEX IF EXISTS \"idx_artwork_key\"")
        createExplicitIndexes(database, contract)
        createTriggers(database, contract)

        // Preserve the established v29 AniList normalization and interrupted-scan semantics.
        if (tableExists(database, "anime")) {
            database.execSQL(
                "UPDATE anime SET anilist_match_status = CASE " +
                    "WHEN metadata_status = 'manual' AND anilist_id IS NOT NULL THEN 'manual' " +
                    "WHEN anilist_id IS NOT NULL THEN 'matched' " +
                    "ELSE COALESCE(NULLIF(anilist_match_status, ''), 'unmatched') END " +
                    "WHERE anilist_id IS NOT NULL OR anilist_match_status IS NULL",
            )
        }
        val timestampSeconds = System.currentTimeMillis() / 1000.0
        database.execSQL(
            "INSERT OR IGNORE INTO schema_migrations(version, applied_at) VALUES (?, ?)",
            arrayOf<Any>(expectedVersion, timestampSeconds),
        )
        if (tableExists(database, "scan_runs")) {
            database.execSQL(
                "UPDATE scan_runs SET status='interrupted', generation_status='FAILED', " +
                    "cancelled=1, finished_at=? WHERE status='running' AND finished_at IS NULL",
                arrayOf<Any>(timestampSeconds),
            )
        }
    }

    private fun createTableSql(table: String, contract: JSONObject): String {
        val tableColumns = contract.getJSONObject("columns").getJSONArray(table).objects()
        check(tableColumns.isNotEmpty()) { "The canonical contract has no columns for $table." }
        val primary = tableColumns
            .filter { it.getInt("primary_key_position") > 0 }
            .sortedBy { it.getInt("primary_key_position") }
        val primaryInline = primary.size == 1
        val definitions = mutableListOf<String>()

        for (column in tableColumns) {
            val name = column.getString("name")
            requireSafeIdentifier(name)
            val type = column.getString("type").trim()
            check(type.matches(Regex("[A-Za-z][A-Za-z0-9 ]{0,31}"))) {
                "Unsupported SQLite declared type for $table.$name."
            }
            val sql = StringBuilder().append(quote(name)).append(' ').append(type)
            if (primaryInline && column.getInt("primary_key_position") == 1) {
                sql.append(" PRIMARY KEY")
            } else if (column.getBoolean("not_null")) {
                sql.append(" NOT NULL")
            }
            if (!column.isNull("default")) sql.append(" DEFAULT ").append(column.getString("default"))
            check(column.optInt("hidden", 0) == 0) {
                "Generated/hidden columns cannot be created from a portable additive contract: $table.$name."
            }
            definitions += sql.toString()
        }

        if (primary.size > 1) {
            definitions += "PRIMARY KEY (" + primary.joinToString(", ") { quote(it.getString("name")) } + ")"
        }

        val indexes = contract.getJSONArray("indexes").objects()
        for (index in indexes.filter { it.getString("table") == table && it.getString("origin") == "u" }) {
            val indexedColumns = index.getJSONArray("columns").objects().sortedBy { it.getInt("column_id") }
            check(indexedColumns.isNotEmpty() && indexedColumns.all { !it.isNull("name") && !it.getBoolean("expression") }) {
                "Cannot safely reconstruct unique constraint ${index.getString("name")}."
            }
            definitions += "UNIQUE (" + indexedColumns.joinToString(", ") { quote(it.getString("name")) } + ")"
        }

        val foreignKeys = contract.getJSONObject("foreign_keys").optJSONArray(table)?.objects().orEmpty()
        for (group in foreignKeys.groupBy { it.getInt("id") }.toSortedMap().values) {
            val ordered = group.sortedBy { it.getInt("sequence") }
            val targetTable = ordered.first().getString("table")
            requireSafeIdentifier(targetTable)
            check(ordered.all { it.getString("table") == targetTable }) {
                "Composite foreign key in $table targets multiple tables."
            }
            val fromColumns = ordered.joinToString(", ") { quote(it.getString("from")) }
            val toColumns = ordered.joinToString(", ") { quote(it.getString("to")) }
            val reference = StringBuilder("FOREIGN KEY ($fromColumns) REFERENCES ${quote(targetTable)} ($toColumns)")
            appendAction(reference, "ON UPDATE", ordered.first().getString("on_update"))
            appendAction(reference, "ON DELETE", ordered.first().getString("on_delete"))
            val match = ordered.first().getString("match")
            if (match != "NONE" && match != "SIMPLE") reference.append(" MATCH ").append(match)
            definitions += reference.toString()
        }

        val tableOptions = contract.getJSONObject("table_contract").getJSONObject(table)
        for (checkExpression in tableOptions.getJSONArray("checks").strings()) {
            definitions += "CHECK ($checkExpression)"
        }
        val suffix = buildString {
            if (tableOptions.optBoolean("without_rowid")) append(" WITHOUT ROWID")
            if (tableOptions.optBoolean("strict")) append(if (isEmpty()) " STRICT" else ", STRICT")
        }
        return "CREATE TABLE ${quote(table)} (" + definitions.joinToString(", ") + ")" + suffix
    }

    private fun addMissingColumns(database: SQLiteDatabase, table: String, expected: JSONArray) {
        val existing = database.rawQuery("PRAGMA table_xinfo(${quote(table)})", null).use { cursor ->
            buildSet {
                while (cursor.moveToNext()) add(cursor.getString(1))
            }
        }
        for (column in expected.objects()) {
            val name = column.getString("name")
            if (name in existing) continue
            check(column.getInt("primary_key_position") == 0) {
                "Cannot add missing primary-key column $table.$name without rebuilding a user table."
            }
            check(column.optInt("hidden", 0) == 0) {
                "Cannot add a generated/hidden column $table.$name without a version-specific migration."
            }
            val defaultMissing = column.isNull("default")
            check(!column.getBoolean("not_null") || !defaultMissing) {
                "Cannot add required column $table.$name without a safe default; recovery is required."
            }
            val type = column.getString("type").trim()
            check(type.matches(Regex("[A-Za-z][A-Za-z0-9 ]{0,31}"))) {
                "Unsupported SQLite declared type for $table.$name."
            }
            val definition = StringBuilder()
                .append("ALTER TABLE ").append(quote(table))
                .append(" ADD COLUMN ").append(quote(name)).append(' ').append(type)
            if (column.getBoolean("not_null")) definition.append(" NOT NULL")
            if (!defaultMissing) definition.append(" DEFAULT ").append(column.getString("default"))
            database.execSQL(definition.toString())
        }
    }

    private fun createExplicitIndexes(database: SQLiteDatabase, contract: JSONObject) {
        for (index in contract.getJSONArray("indexes").objects().filter { it.getString("origin") == "c" }) {
            val name = index.getString("name")
            val rawSql = index.optString("sql").trim()
            check(rawSql.isNotEmpty()) { "Canonical index $name has no SQL definition." }
            val createPattern = Regex("(?i)^CREATE\\s+(UNIQUE\\s+)?INDEX\\s+")
            check(createPattern.containsMatchIn(rawSql)) { "Unsupported DDL for canonical index $name." }
            val prefix = "CREATE " + (if (createPattern.find(rawSql)?.groupValues?.get(1).orEmpty().isNotBlank()) "UNIQUE " else "") + "INDEX IF NOT EXISTS "
            database.execSQL(rawSql.replaceFirst(createPattern, prefix))
        }
    }

    private fun createTriggers(database: SQLiteDatabase, contract: JSONObject) {
        val triggers = contract.optJSONObject("triggers") ?: return
        val iterator = triggers.keys()
        while (iterator.hasNext()) {
            val name = iterator.next()
            val trigger = triggers.getJSONObject(name)
            val sql = trigger.optString("sql").trim()
            check(sql.isNotEmpty()) { "Canonical trigger $name has no SQL definition." }
            val pattern = Regex("(?i)^CREATE\\s+TRIGGER\\s+")
            check(pattern.containsMatchIn(sql) || sql.startsWith("CREATE TRIGGER IF NOT EXISTS", ignoreCase = true)) {
                "Unsupported DDL for canonical trigger $name."
            }
            database.execSQL(sql.replaceFirst(pattern, "CREATE TRIGGER IF NOT EXISTS "))
        }
    }

    private fun appendAction(target: StringBuilder, clause: String, action: String) {
        val allowed = setOf("NO ACTION", "RESTRICT", "SET NULL", "SET DEFAULT", "CASCADE")
        check(action in allowed) { "Unsupported SQLite foreign-key action: $action" }
        if (action != "NO ACTION") target.append(' ').append(clause).append(' ').append(action)
    }

    private fun tableExists(database: SQLiteDatabase, table: String): Boolean =
        database.rawQuery("SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1", arrayOf(table))
            .use { it.moveToFirst() }

    private fun pragmaInt(database: SQLiteDatabase, pragma: String): Int =
        database.rawQuery(pragma, null).use { cursor ->
            check(cursor.moveToFirst()) { "SQLite did not return $pragma." }
            cursor.getInt(0)
        }

    private fun quote(identifier: String): String {
        requireSafeIdentifier(identifier)
        return "\"" + identifier.replace("\"", "\"\"") + "\""
    }

    private fun requireSafeIdentifier(identifier: String) {
        require(identifier.matches(Regex("[A-Za-z_][A-Za-z0-9_]*"))) {
            "Invalid canonical SQLite identifier."
        }
    }

    private fun JSONArray.strings(): List<String> = buildList {
        for (index in 0 until length()) add(getString(index))
    }

    private fun JSONArray.objects(): List<JSONObject> = buildList {
        for (index in 0 until length()) add(getJSONObject(index))
    }

    private const val SCHEMA_MIGRATIONS_TABLE = "schema_migrations"
}
